/* mail-tpl-a: family and friends. Mom, Dad, Gran (ALL CAPS), the cousin (Cast 'cousin'), Dave, the cousin's big brother (Cast 'cousin2'), Gubbinz (Orky), Jack the editor,
 * a pen pal, school, the football team, plus the postman (bounces) and the chain letter that never ends.
 * Template language: {a|b} one of, {=var} context value, {?40:text} sometimes. See mail-gen.js. */
(function () {
  'use strict';
  const G = window.MailGen; if (!G) return;
  const add = G.add;
  const has = re => (c) => re.test(c.said || '');
  G.FX.gran = (s, r) => G.FX.caps(G.FX.typo(s, r), r);
  G.contacts = (G.contacts || []).concat([
    [Cast.t('Cousin {cousin}'), Cast.t('Cousin {cousin} <{cousin?popprince|popprincess}_{cousin.slug}@hotjack.jnet>')], ['Gubbinz', 'Gubbinz <gubbinz@squigpen.grot>'], ['Jack (JACK ATTACK! Online)', 'Jack <jack@jackattack.jnet>'],
    ['Mrs Hargreaves (Homework Club)', 'Mrs Hargreaves <homework@skool.kidz>'], ['Coach Terry (Rovers Juniors)', 'Coach Terry <coach@roversjuniors.jnet>'], ['Da Gem Exchange', 'Da Gem Exchange <orders@gemexchange.grot>'],
  ]);

  // ================================================================ MOM
  add('mom', {
    from: 'Mom <the.family@jacknet.jnet>', addrs: ['the.family@jacknet.jnet', 'mom@jacknet.jnet'], w: 3,
    wrap: '{=hi}\n\n{=body}\n\n{=bye}',
    v: {
      hi: c => c.guest ? ['{=name},', 'Hello {=name} (is that what we\'re calling you now?),', 'Hello love,', 'Dear {=name} (Dad says that\'s your Internet name),'] : ['{=name},', 'Hello {=name},', 'Hi love,', '{=name} -', 'Dear {=name},', 'Morning {=name},'],
      bye: ['Love Mom x', 'Mom x', 'Love from Mom xx', 'Mom (downstairs)', 'Love you, Mom x', 'Mom\n\n(I know you\'re reading this. The modem light is on.)'],
    },
    ps: ['P.S. {=mom}', 'P.S. Your father says hello. He still can\'t work the e-mail.', 'P.S. Have you seen the remote control?', 'P.S. Tea is at six. Not "five more minutes past six". Six.', 'P.S. There is a pile of clean washing on the stairs. It will not walk up by itself.',
      'P.S. Who keeps putting the cereal box back empty?', 'P.S. I have learned how to do a smiley face. :-) Isn\'t that clever.', 'P.S. Somebody has used all the sticky tape. I\'m not saying who. (It was you.)', 'P.S. {=wx} Take a coat.'],
    mails: [
      { w: 2, subj: '{Your room|YOUR ROOM|Bedroom|Re: your room (again)}', body: `{Your room needs tidying.|Please tidy your room.|Your room. Tidy it.|I went into your room today.} {I went in to get the washing and I couldn't find the floor.|There is a plate in there that I think has been there since {=monthname}.|Something in there is making a noise and I don't think it's the computer.|I trod on a BLOCKO brick and said a word I'm not proud of.|There are more cups in your room than in the kitchen.|Why is there glue on the curtains?} {I am not asking again.|This is the {=n1}th time I've asked.|You've got till {=tomorrow}.|Then you can go on the computer.|If it's not done by tea time, the modem goes in my handbag.}` },
      { w: c => c.school || (c.sun && c.term) ? 3 : 0, subj: '{Homework|homework FIRST|Have you done your homework?}', body: `Homework first. Then the computer. {I know you said you'd done it.|I saw your bag. Your homework is still in it.|Mrs Hargreaves sent a letter home about the homework. Nothing bad. But still.|And "I'll do it in the morning" is not a plan.} {=mom}` },
      { w: 2, subj: '{I NEED THE PHONE|Get off the Internet please|The phone!!!|PHONE}', body: `Get off the Internet, I need the phone! {Gran has been trying to ring for an hour.|I have been trying to ring the dentist since four o'clock.|Your Aunty Pat says she keeps getting a noise like a fax machine.|Dad's trying to ring from work and it's been engaged all afternoon.} {The phone bill came. We need to have a chat about the phone bill.|Half an hour more, then off.|I don't care if it's "nearly downloaded".}` },
      { w: 2, subj: '{Tea|Tea\'s nearly ready|Tea in {ten|twenty|five} minutes}', body: `Tea's ready in {ten|twenty|five} minutes. It's {fish fingers|spag bol|shepherd's pie|chicken nuggets and beans|sausage and mash|pizza (the good frozen one)|soup (don't make that face)|chicken curry (the mild one)|jacket potatoes}. {Come down when I call you, not three calls after.|If I have to come up those stairs...|Wash your hands. The mouse is filthy.|Then you can have half an hour more on the computer.}` },
      { w: c => c.sat || c.sun ? 3 : 0, subj: '{This weekend|Weekend plans|Sunday|Tomorrow}', body: `{This weekend|Tomorrow} we're {going round Gran's for Sunday dinner|doing the big shop, you're coming|washing the car with Dad|sorting out your cupboard (I mean it this time)|visiting Aunty Pat|going to the garden centre (yes, again)}. {No arguing.|There might be a trip to the video shop afterwards if you're good.|You can bring your Game Lad in the car.|Wear something that isn't covered in paint.}` },
      { w: c => c.schoolTomorrow ? 2 : 0, subj: '{School night!|Bedtime|Computer off by {eight|half eight|nine}}', body: `School night! Computer off by {eight|half eight|nine}. {I mean it this time.|The modem light is very bright from the landing.|Your PE kit needs to go in your bag tonight, not in the morning.} {Pack your bag.|Don't forget your dinner money.|Have you got a clean shirt?}` },
      { w: c => c.hasGame ? 2 : 0, subj: '{That game|Re: {=game}|The noise}', body: `Is {=game} the one with all the {shouting|music|explosions|beeping}? {I could hear it from the kitchen.|Your Dad wants a go. Let him have a go. He won't be very good.|Please turn the sound down a bit. The dog's hiding.|It looks very clever. I didn't understand any of it.}` },
      { w: 1, subj: '{What is this {=craze} thing?|{=craze}?|Question}', body: `What is this {=craze} business? {Everyone at the school gate is talking about it.|The lady from next door's little one won't stop going on about it.|Do you want one? Is that what all this is leading up to?|In my day it was clackers.}` },
      { w: c => c.hasNo1 ? 1 : 0, subj: '{The radio|That song|Number one}', body: `Have you heard {=no1}? It's number one. {I quite like it.|Your Dad doesn't.|I've heard it on the radio fourteen times today.|I did a little dance in the kitchen. Nobody saw. (The dog saw.)}` },
      { w: 1, subj: '{The shopping|Shopping list|Can you add to the list}', body: `I'm doing the shopping list. {Do you want anything?|Write it on the list on the fridge, not on an e-mail.|We've got: bread, milk, beans, the cereal you like.} {And no, "a {=saving}" is not shopping.|I'm not buying any more of those yoghurts you don't eat.|Yes, I'll get crisps.}` },
      { w: 1, subj: '{Well done|I\'m proud of you|A little note}', body: `{Just a little note to say I'm proud of you.|I saw that thing you made on the computer. It's very clever.|Thank you for helping with the washing up yesterday. I nearly fainted.} {Don't tell anyone I sent you a soppy e-mail.|Now go and tidy your room. (Sorry, couldn't help it.)|Love you lots.}` },
      { w: c => c.ev.size ? 0 : 1, subj: '{Dentist|Haircut|Appointment}', body: `{You've got the dentist on {=tomorrow}.|Haircut on {=tomorrow}. And no, you can't have it like that man in the film.|Opticians on {=tomorrow} after school.} {I've written it on the calendar.|Don't make that face, I can hear you making it.}` },
      { must: c => c.is('newyear'), subj: 'Happy New Year!', body: `Happy New Year, {=name}! 1999! The last year of the 1900s! {Make it a good one.|Don't spend all of it on that computer.} {New Year's resolutions please: one, tidy room. Two, see one.|I've made a resolution to learn the e-mail properly. As you can see, it's going very well.}` },
      { must: c => c.is('pancake'), subj: 'PANCAKE DAY!!!', body: `It's Pancake Day! {Lemon and sugar or golden syrup?|We're having them for tea. And pudding. Possibly breakfast tomorrow.} Flipping competition after tea. {Last year Dad got one stuck on the ceiling.|The dog is ready and waiting.|I want to see a proper flip this year, not a flop.}` },
      { must: c => c.is('mothers'), subj: 'Thank you xxx', body: `Thank you for my card{ and the flowers| and the breakfast in bed (the toast was very... crunchy)| and the lovely poem}. It's on the mantelpiece. {I know Dad reminded you. That's all right, it still counts.|I had a little cry. Don't tell your father.}` },
      { w: c => c.is('easter') ? 5 : 0, subj: '{Easter eggs|Chocolate}', body: `Easter eggs are NOT breakfast. {I've counted them.|One a day.|Gran's sent another one. That makes {=n1}.} {And save one for your Dad.|And don't let the dog anywhere near them.}` },
      { w: c => c.is('fathersrun') ? 6 : 0, subj: 'Father\'s Day on Sunday (shhh)', body: `Don't forget it's Father's Day on Sunday! {I've got a card, you just sign it.|He wants socks. He always wants socks.|We're doing him a fry-up. You're on toast.} Don't say anything!` },
      { must: c => c.is('eclipse'), subj: 'DO NOT LOOK AT THE SUN', prio: true, body: `It's the eclipse today. DO NOT look at the Sun. I mean it. Use the proper glasses or the pinhole box. {I've put the glasses by the back door.|Your Dad's going to watch it on the telly at work.|Not even for a second. Not even a bit.} {I'll be in the garden at eleven if you want to watch it together.|It's going to go dark in the middle of the morning. Spooky!}` },
      { must: c => c.is('schoolsout'), subj: 'Last day of term!', body: `Last day of term! Well done. {Your report's on the kitchen table. We'll talk about it. It's mostly good!|Six weeks. SIX WEEKS. We need a plan, and the plan isn't "the computer".} {I'll get some ice lollies in.|Bring your PE kit home. All of it. Even the sock.}` },
      { w: c => c.is('backrun') || c.is('backtoschool') ? 6 : 0, subj: '{New school shoes|Back to school}', body: `{New school shoes are in the hall. Try them on.|Your uniform's ironed and on your chair.|I've put your name in everything. Even your pencil case.} {Back to school on Monday! Early night on Sunday.|No more pyjamas till lunchtime.}` },
      { w: c => c.is('halloweenrun') || c.is('halloween') ? 4 : 0, subj: '{Halloween|Trick or treat}', body: `If you're going trick or treating, {you're going with Dave and his mom|you're back by seven|you're taking a torch}. {And no eggs.|Only knock on doors with a pumpkin outside.|I've bought sweets for the door. Don't eat them all before anyone comes.}` },
      { must: c => c.is('bonfire'), subj: 'Bonfire Night!', body: `It's Bonfire Night tonight! {Wrap up warm.|Wellies on, it'll be muddy.|Sparklers: gloves ON, and stand still.} {We're going to the big display at the park.|Dad's doing the fireworks in the garden. Stand WELL back.|Hot dogs first, then fireworks.}` },
      { w: c => c.is('clocksback') || c.is('clocksfwd') ? 6 : 0, subj: 'The clocks', body: c => `The clocks go ${c.m === 3 ? 'forward' : 'back'} {tonight|this weekend}. ${c.m === 3 ? 'One hour LESS in bed. Sorry!' : 'An extra hour in bed!'} {The video will be flashing 12:00 again.|Dad will forget to change the car clock again.|The computer does it by itself. Clever computer.}` },
      { w: c => c.is('y2k') ? 3 : 0, subj: '{The Millennium|Millennium Bug|Beans}', body: `{I've bought more candles.|We've got enough beans for a month.|I've written all the phone numbers down on paper, just in case.|Dad's filled the bath with water "just in case". I'd like my bath back.} {Is your computer Millennium Bug proof?|Can you check the video recorder knows about 2000?|Your Dad says it'll all be fine. Your Dad said that about the shed roof.}` },
      { w: c => c.is('advent') ? 3 : 0, subj: '{Christmas list|Christmas|Advent calendar}', body: `{Have you written your Christmas list yet? A REALISTIC one.|Who opened tomorrow's door on the advent calendar?|Gran wants to know what you want for Christmas. "Money" is not an answer, apparently.} {We'll see.|Father Christmas reads e-mails too, you know.}` },
      { must: c => c.is('xmas'), subj: 'Merry Christmas!!!', body: `Merry Christmas, {=name}! Why are you on the computer on Christmas Day?! {Come downstairs, Gran's here.|Dinner is at two. The sprouts are on. (They've been on since Tuesday.)|Your Dad's trying to build your present and he's lost a screw.} Love you lots. xxx` },
      { must: c => c.is('nye'), subj: 'New Year\'s Eve', body: `{Have fun at Dave's tonight!|It's the last night of the 1900s!} {Back by half past twelve. Dad's picking you up.|We'll be watching it all on the telly.} {If the lights go off at midnight, don't panic. It'll be the Millennium Bug. Or your Dad.|Happy New Year when it comes! Imagine: 2000!}` },
      { w: c => c.is('summerhols') ? 2 : 0, subj: '{Sun cream|Out in the sun|Holidays}', body: `{Sun cream! Both arms!|It's a lovely day. Why are you indoors?|Go outside. It's called the Outside. You'll like it.} {Take a drink with you.|Back by tea.|Take the dog.}` },
    ],
    night: { subj: '{WHY ARE YOU STILL UP|BED!!!|It is {=clock}}', secret: 'mail.midnight', body: `{=name},\n\nIt is {=clock}. I can see the light from the computer under your door.\n\n{BED.|Bed. Now. The Internet will still be there in the morning.|I am going to count to ten. I am typing this on the computer downstairs. I am still counting.|Whatever you're doing, it can wait. Go to sleep.}\n\nMom\n\nP.S. Yes, I know how to send e-mails now. {I've been practising.|Your Dad showed me.|Be afraid.}` },
    replyDelay: [60, 160],
    reply: [
      { w: (c) => /dreamcast/i.test(c.said), body: `{=name},\n\nWe'll see.\n\nMom x\n\n{=quote}` },
      { w: (c) => /money|pocket|£|quid/i.test(c.said), body: `{=name},\n\nNice try.\n\nLove Mom x\n\nP.S. Your room's still not tidy.\n\n{=quote}` },
      { w: (c) => /sorry/i.test(c.said), body: `{=name},\n\nApology accepted. Room still needs tidying.\n\nLove Mom x\n\n{=quote}` },
      { w: (c) => /\?/.test(c.said), body: `{=name},\n\nThe answer is no.\n\n(Whatever it was. Come down and ask me properly and it might be "maybe".)\n\nLove Mom x\n\n{=quote}` },
      { body: `{=name},\n\nWhy are you e-mailing me? I'm in the kitchen. You could have just shouted.\n\nBut thank you, it was a lovely surprise. {I've printed it out.|I showed your father. He said "how did you do that?"}\n\nLove Mom x\n\n{=quote}` },
    ],
  });

  // ================================================================ DAD (at work)
  const DADJOKES = [
    ['You know you\'re addicted to the Internet when...', ` - You wake up at 3am and check your e-mail on the way back from the loo.\n - Your dog has its own home page.\n - You can't phone your Mom. She hasn't got a modem.\n - You tell the taxi driver you live at http://www.yourhouse.jnet\n - You turn the computer off and feel a bit lonely.\n - You try to double-click the telly.\n - You laugh at jokes that end in ".jnet".`],
    ['Computer terms explained (for Dads)', ` FLOPPY DISK: a disk that is not floppy.\n HARD DISK: a disk you can't see, that is somehow harder.\n MOUSE: not a mouse. Do not feed it.\n RAM: not a sheep.\n MEGABYTE: what your Mom does to your dinner if you're late.\n CRASH: what the computer does when you've nearly finished.\n SAVE: what you should have done before the crash.\n CD-ROM: a coaster that cost £30.`],
    ['Signs your PC is too old', ` - Your "turbo" button makes it slower.\n - The manual is written on parchment.\n - You have to wind it up.\n - It takes longer to start than the car.\n - Solitaire runs in black and white.\n - It's got a Millennium Bug AND a Victorian Bug.`],
    ['The Office Computer Rules', ` 1. If it's working, don't touch it.\n 2. If it's not working, turn it off and on again.\n 3. If that doesn't work, find someone under 15.\n 4. If you can't find someone under 15, go home.\n 5. Never let the boss see you playing Minesweeper. Unless he's winning.`],
    ['Thought for the day', ` A computer once beat me at chess.\n But it was no match for me at kickboxing.\n\n (Bob in Accounts sent me this. Bob thinks it's the funniest thing ever written. Bob is wrong. It's the second funniest.)`],
    ['How to tell if you\'re a modem', ` - You make a noise like a robot gargling whenever someone picks up the phone.\n - Nobody can talk to your Mom while you're busy.\n - You promise 56K and deliver about 40.\n - Everyone in the house hates you between 6 and 8pm.`],
    ['Why the chicken crossed the road (computer edition)', ` JACKOS: The chicken will cross the road after a short pause. Please wait...\n THE INTERNET: The chicken is crossing the road. 12% complete. Time remaining: 4 hours.\n PRINTER: The chicken cannot cross the road. The chicken is out of cyan.\n Y2K: The chicken will cross the road in 1900. The road has not been built yet.\n SCREENSAVER: The chicken is flying through space with some toasters.`],
    ['You might be a 1999 Dad if...', ` - You have a mobile phone the size of a brick and you're proud of it.\n - You've said "it's all on the Internet now" this week.\n - You've printed out an e-mail to read it.\n - You have opinions about Championship Manager.\n - You've told someone the video recorder "just needs a bit of a tap".`],
  ];
  add('dad', {
    from: 'Dad (at work) <dad.at.work@jacknet.jnet>', addrs: ['dad.at.work@jacknet.jnet'], w: 1.6,
    wrap: '{=hi}\n\n{=body}\n\n{=bye}',
    v: { hi: ['Hi {=name},', 'Hello {=name},', 'Alright {=name}?', '{=name},', 'Hello from the office,'], bye: ['Dad', 'Love Dad', 'Dad\n(sent from work, don\'t tell my boss)', 'Dad\n----------------------------------------\nThis e-mail is confidential. If you are not {=name}, please tell Dad, he will be very confused.', 'Cheers,\nDad'] },
    ps: ['P.S. Don\'t tell your Mom I sent you this from work.', 'P.S. How do I make the writing bigger?', 'P.S. Bob in Accounts says hello. You don\'t know Bob. Nobody really knows Bob.', 'P.S. The printer here is out of cyan as well. It\'s a worldwide cyan shortage.'],
    mails: [
      { w: 3, nowrap: 1, nops: 1, subj: 'FW: FW: {=jt}', v: { jt: '' }, body: '', after: (o, c, r) => { const j = G.pick(DADJOKES, r); o.subj = 'FW: ' + (r() < 0.6 ? 'FW: ' : '') + j[0]; o.body = `${G.pick(['Thought you\'d like this. Bob sent it round the whole office.', 'Ha! This one made me laugh.', 'Sorry. I couldn\'t not.', 'This is going round at work.'], r)}\n\nDad\n\n-----Original Message-----\nFrom: Bob (Accounts)\nSubject: ${j[0]}\n\n${j[0].toUpperCase()}\n\n${j[1]}`; } },
      { w: c => c.md >= 326 ? 2 : 0, subj: '{Championship Manager|CM3|Football management}', body: `{I've got my team to the top of the league.|I've been sacked again in Championship Manager.|I signed a 16-year-old from Peru and he's scored 40 goals.|I was up till 2am "just finishing a season".} {Don't tell your Mom how late I was up.|Do you want a go at the weekend? You can be my assistant manager.|It's very educational. It's maths, really.}` },
      { w: c => c.md >= 1101 ? 2 : 0, subj: 'Homeworld', body: `{I've stopped Championship Manager for this space game, Homeworld.|You can spin the camera round your whole space fleet in Homeworld.} {It looks like a screensaver.|I spent an hour just looking at the ships.|Your Mom asked if it was a film.} {Have a go when you're back from school.|Mind you don't lose my save.}` },
      { w: 1.5, subj: '{The shelf|The shed|DIY}', body: `{I'm going to put that shelf up in your room this weekend.|The shed roof is leaking again. I fixed it. It's leaking a different bit now.|I've bought a drill. A proper one.} {Don't put anything heavy on the shelf. Or anything.|Your Mom has "concerns".|How hard can it be?}` },
      { w: c => c.is('y2k') ? 3 : 0, subj: '{Y2K at work|Millennium Bug meeting|Millennium}', body: `{We had a Millennium Bug meeting at work today. Two hours. Nobody knows anything.|The IT man has put "Y2K COMPLIANT" stickers on all the computers. I'm not sure he checked.|They've asked me to come in on New Year's Day "to check the computers still work". On New Year's Day!} {Is the home PC OK?|You know more about this than our IT man.|I've told your Mom it'll be fine. Please make it be fine.}` },
      { w: c => c.is('mothersrun') ? 8 : 0, subj: 'DON\'T FORGET - Mother\'s Day', body: `Don't forget, Mother's Day is on Sunday! {I've got a card, you sign it.|We're doing breakfast in bed. You're in charge of toast. Don't burn it.|Flowers are hidden in the shed.} Don't say anything to your Mom!` },
      { must: c => c.is('fathers'), subj: 'Thanks for the card', body: `Thanks for my Father's Day card{ and the socks| and the mug| and the breakfast}. {I love socks. You can never have too many socks.|Best Father's Day ever.} {Fancy a game of {=game} later? You'll have to show me which buttons.|Let's go to the park later.}` },
      { w: c => c.hasGame ? 1.5 : 0, subj: '{=game}', body: `{Can I have a go on {=game} tonight?|I had a go on {=game} while you were at school. I think I broke your high score. Sorry.|Bob in Accounts' son has got {=game}. Is it any good?} {I'll be very good. You'll see.|Don't wipe my save.}` },
      { w: c => c.wkend ? 1 : 0.6, subj: '{The car|Car boot sale|Sunday}', body: `{Car boot sale on Sunday morning. Coming? You might find some old games.|I'm washing the car tomorrow. Paying 50p.|The car's making a noise again. Like a modem.} {Bring your pocket money.|Early start!}` },
      { w: c => c.is('eclipse') ? 3 : 0, subj: 'Eclipse at work', body: `We're all going in the car park at work to watch the eclipse. {Bob has made a pinhole box out of a cereal packet.|Somebody brought welding glass.|The boss is going to give a speech. About the eclipse.} {Hope you saw it!|Did it go dark at home?}` },
      { w: c => c.is('nye') || c.is('betwixt') ? 2 : 0, subj: 'The big night', body: `{Big night on Friday!|Nearly the year 2000!} {I'm wearing my party shirt. Your Mom says no.|Have a great time at Dave's.|Let me know if the computer survives midnight.}` },
    ],
    reply: [{ from: 'Dad (at work) <dad.at.work@jacknet.jnet>', subj: 'Out of Office AutoReply: {=re}', secret: 'mail.ooo', body: `This is an automatic reply.\n\nI am currently out of the office {in a meeting|at lunch|on a training course called "E-mail and You"|at the dentist|in the kitchen (working from home today)}. I will reply to your message when I get back, or when I work out how this e-mail thing works.\n\nIf your message is urgent, please contact my secretary, who is your Mom.\n\nDad\n\n----------------------------------------\n{=quote}` }],
  });

  // ================================================================ GRAN (everything is in capitals)
  add('gran', {
    from: 'Gran <gran.and.grandad@jacknet.jnet>', addrs: ['gran.and.grandad@jacknet.jnet', 'gran@pensionernet.jnet'], w: 2.6, fx: 'gran',
    wrap: '{=hi}\n\n{=body}\n\n{=bye}',
    v: {
      hi: c => c.guest ? ['HELLO {=name}. IS THAT YOUR REAL NAME. GRANDAD SAYS IT IS A COMPUTER NAME.', 'DEAR {=name} (GRANDAD SAYS THAT IS WHAT YOU ARE CALLED ON THE INTERNET)', 'HELLO DEAR'] : ['HELLO {=name}', 'DEAR {=name}', 'HELLO {=name} IT IS GRAN', 'HELLO TO MY FAVOURITE GRANDCHILD {=name}', 'HELLO {=name} THIS IS GRAN AGAIN', 'HELLO {=name} DEAR'],
      bye: ['LOVE GRAN XXXX', 'LOTS OF LOVE GRAN AND GRANDAD XXX', 'LOVE FROM GRAN\n\nP.S. HOW DO I SEND THIS', 'GRAN XXXXXXX (GRANDAD SAYS THAT IS TOO MANY KISSES)', 'LOVE GRAN\nGRANDAD SAYS HELLO', 'GRAN\n(MRS)'],
    },
    ps: ['P.S. DID YOU GET THE SOCKS.', 'P.S. I CANNOT FIND THE BUTTON FOR SMALL LETTERS STILL.', 'P.S. GRANDAD SAYS THE INTERNET IS COSTING A FORTUNE.', 'P.S. TELL YOUR MOM I WILL RING HER. IF THE PHONE IS NOT BUSY WITH THE INTERNET.', 'P.S. I HAVE PUT A FIVE POUND NOTE IN THE POST FOR YOU. DO NOT TELL GRANDAD.', 'P.S. WHAT IS A WEB SITE.'],
    mails: [
      { w: 2, subj: '{HELLO|HELLO FROM GRAN|ARE YOU THERE|TESTING}', body: `{I AM JUST WRITING TO SAY HELLO.|GRANDAD HAS GONE TO THE SHOPS SO I AM ON THE COMPUTER.|I HAVE WORKED OUT THE E-MAIL ALL BY MYSELF TODAY.} {=wx} {GRANDAD HAS BEEN IN THE GARDEN ALL DAY.|THE CAT NEXT DOOR HAS BEEN IN OUR GARDEN AGAIN.|I WENT TO BINGO AND I NEARLY WON.|DORIS FROM NUMBER {=n2} SENDS HER LOVE.} {ARE YOU EATING PROPERLY.|ARE YOU BEING GOOD FOR YOUR MOM.|I HOPE YOU ARE WEARING A VEST.}` },
      { w: 2, subj: '{KNITTING|A JUMPER FOR YOU|I AM KNITTING}', body: `I AM KNITTING YOU A JUMPER. IT IS {GREEN|ORANGE|BROWN|STRIPY|THE COLOUR OF ONE OF YOUR LITTLE GREEN MEN}. {IT HAS A PICTURE ON THE FRONT OF A SPACE ROCKET.|I HAVE DONE ONE ARM. THE OTHER ARM IS GOING TO BE LONGER.|IT WILL BE READY FOR {CHRISTMAS|YOUR NEXT VISIT|THE WINTER}.} {WHAT SIZE ARE YOU NOW.|YOU WILL GROW INTO IT.}` },
      { w: 1.5, subj: '{THE COMPUTER|COMPUTER PROBLEM|HOW DO I}', body: `{THE COMPUTER MADE A NOISE AGAIN WHEN IT WENT ON THE INTERNET. GRANDAD SAYS THAT IS NORMAL.|THE LITTLE ARROW HAS GONE OFF THE SIDE OF THE SCREEN AND I CANNOT GET IT BACK.|I PRESSED A BUTTON AND EVERYTHING WENT BLUE. GRANDAD TURNED IT OFF AT THE WALL.|HOW DO YOU DO THE SMALL LETTERS. I HAVE ASKED GRANDAD AND HE DOES NOT KNOW EITHER.|THE MOUSE IS NOT WORKING. GRANDAD SAYS I HAVE TO TAKE THE BALL OUT AND CLEAN IT. I DID NOT KNOW IT HAD A BALL.} {CAN YOU COME AND HAVE A LOOK AT IT.|YOU ARE SO CLEVER WITH COMPUTERS.|I HAVE WRITTEN IT DOWN SO I REMEMBER.}` },
      { w: 1.5, subj: '{MILLIONAIRE|DID YOU SEE IT|THE TELEVISION}', body: `DID YOU SEE {WHO WANTS TO BE A MILLIONAIRE|MILLIONAIRE} LAST NIGHT. {A MAN GOT TO SIXTY FOUR THOUSAND POUNDS AND THEN HE GOT IT WRONG.|I KNEW ALL THE ANSWERS UNTIL THE HARD ONES.|GRANDAD SAYS HE WOULD ASK THE AUDIENCE. I SAID THE AUDIENCE DOES NOT KNOW HIM.} {I WOULD SPEND THE MONEY ON A NEW KETTLE.|IS IT FINAL ANSWER OR FINAL ANSWER.}` },
      { w: c => c.hasGame ? 1 : 0, subj: 'YOUR GAMES', body: `YOUR MOM SAYS YOU ARE PLAYING {=game^} ON {=gameOn^}. {IS IT A NICE GAME.|IS IT VERY VIOLENT.|GRANDAD WANTS TO KNOW IF IT IS LIKE SPACE INVADERS.|I PLAYED A GAME ON THE COMPUTER CALLED SOLITAIRE. THE CARDS ALL JUMPED ABOUT AT THE END. I THINK I WON.} {DO NOT PLAY IT TOO LATE.|YOU WILL GET SQUARE EYES.}` },
      { w: c => c.hasNo1 ? 1 : 0, subj: 'THE RADIO', body: `I HEARD {=no1^} ON THE RADIO. {IT WAS VERY LOUD.|I DID NOT UNDERSTAND THE WORDS.|GRANDAD TURNED IT OFF.|IT WAS QUITE CATCHY ACTUALLY.} {IN MY DAY WE HAD PROPER SINGERS.|IS THAT THE ONE YOU LIKE.}` },
      { w: c => c.crazes.length ? 1 : 0, subj: 'A QUESTION', body: `WHAT IS {=craze^}. DORIS'S GRANDSON {WANTS ONE|HAS GOT ONE|WILL NOT STOP TALKING ABOUT IT}. {DO YOU WANT ONE TOO.|IS IT EXPENSIVE.|I COULD KNIT ONE.}` },
      { w: 1, subj: 'FW: FW: FW: {FUNNY|VERY FUNNY|MUST READ}', body: `{DORIS SENT ME THIS. IT IS VERY FUNNY.|THIS CAME FROM MY FRIEND AT CHURCH.|I DO NOT UNDERSTAND THIS BUT DORIS SAYS IT IS FUNNY.} \n\n>> {WHY DID THE COMPUTER GO TO THE DOCTOR. BECAUSE IT HAD A VIRUS.|WHAT DO YOU CALL A COMPUTER THAT SINGS. A SING-PUTER.|WHY WAS THE COMPUTER COLD. IT LEFT ITS JACKOS OPEN.|WHAT DID THE MOUSE SAY TO THE KEYBOARD. YOU ARE MY TYPE.}\n\n{HA HA HA.|I LAUGHED SO MUCH.|GRANDAD DID NOT LAUGH.}` },
      { w: c => c.is('valrun') || c.is('valentine') ? 6 : 0, subj: 'VALENTINES', body: `HAPPY VALENTINES DAY {=name^}. {IS THERE ANYONE SPECIAL. YOU CAN TELL GRAN.|GRANDAD BOUGHT ME FLOWERS FROM THE GARAGE. HE THINKS I DID NOT NOTICE THE PRICE STICKER.|I HAVE SENT YOU A CARD IN THE POST. IT IS FROM A SECRET ADMIRER. (IT IS FROM ME.)}` },
      { w: c => c.is('pancake') ? 6 : 0, subj: 'PANCAKES', body: `IT IS PANCAKE DAY. {I AM MAKING PANCAKES FOR GRANDAD. HE HAS HAD SIX.|I TOSSED ONE AND IT LANDED ON THE CAT.|LEMON AND SUGAR IS THE ONLY PROPER WAY.}` },
      { w: c => c.is('easter') || c.is('easterhols') ? 3 : 0, subj: 'EASTER', body: `I HAVE GOT YOU AN EASTER EGG. A CHOCOLATE ONE NOT A REAL ONE. {IT IS IN THE CUPBOARD.|DO NOT EAT IT ALL AT ONCE.|GRANDAD HAS EATEN THE LITTLE ONE THAT CAME WITH IT.}` },
      { must: c => c.is('eclipse'), subj: 'THE ECLIPSE IS TODAY', body: `THE ECLIPSE IS TODAY. {DO NOT LOOK AT IT.|GRANDAD HAS MADE A BOX WITH A HOLE IN IT.|I REMEMBER THE LAST ONE. I WAS A LITTLE GIRL.} {I AM GOING TO WATCH IT ON THE TELEVISION WHERE IT IS SAFE.|WILL THE BIRDS GO TO SLEEP.}` },
      { w: c => c.is('halloweenrun') ? 3 : 0, subj: 'HALLOWEEN', body: `ARE YOU GOING TRICK OR TREATING. {WE HAVE BOUGHT SWEETS FOR THE DOOR.|GRANDAD IS GOING TO HIDE IN THE KITCHEN.|IN MY DAY WE JUST HAD A TURNIP.}` },
      { w: c => c.is('bonfirerun') || c.is('bonfire') ? 4 : 0, subj: 'BONFIRE NIGHT', body: `{GRANDAD IS DOING SPARKLERS IN THE GARDEN.|THE CAT HAS GONE UNDER THE BED BECAUSE OF THE FIREWORKS.|WRAP UP WARM FOR THE BONFIRE.} {REMEMBER REMEMBER THE FIFTH OF NOVEMBER.|HAVE A TOFFEE APPLE FOR ME.}` },
      { w: c => c.is('y2k') ? 3 : 0, subj: '{THE MILLENNIUM BUG|Y2K|IS THE COMPUTER SAFE}', body: `{GRANDAD HAS UNPLUGGED THE TOASTER JUST IN CASE.|IS THE MILLENNIUM BUG GOING TO GET INTO OUR COMPUTER.|DORIS SAYS THE BANKS WILL STOP. I HAVE TAKEN OUT TWENTY POUNDS.|WILL THE COMPUTER STILL WORK IN THE YEAR 2000. GRANDAD SAYS HE WILL WAIT AND SEE.} {YOU WILL KNOW. YOU ARE GOOD WITH COMPUTERS.|I HAVE BOUGHT A TORCH.}` },
      { w: c => c.is('advent') ? 4 : 0, subj: '{CHRISTMAS|WHAT DO YOU WANT FOR CHRISTMAS}', body: `WHAT DO YOU WANT FOR CHRISTMAS. {YOUR MOM SAYS YOU WANT {=saving^}. I DO NOT KNOW WHAT THAT IS.|I WAS GOING TO GET YOU SOCKS.|DORIS GOT HER GRANDSON A POKEYMAN. IS THAT A GOOD PRESENT.} {PLEASE TELL ME SOON SO I CAN GO TO THE SHOPS.|I DO NOT GO IN THE BIG SHOPS ANYMORE.}` },
      { must: c => c.is('xmaseve'), subj: 'CHRISTMAS EVE', body: `IT IS CHRISTMAS EVE. {WE ARE COMING ROUND TOMORROW AT ELEVEN.|I HAVE WRAPPED YOUR PRESENTS. ONE OF THEM IS SOCKS.|GRANDAD IS WATCHING A FILM WITH HIS EYES SHUT.} {BE GOOD OR FATHER CHRISTMAS WILL NOT COME.|GO TO SLEEP EARLY.}` },
      { w: c => c.is('summerhols') ? 1.5 : 0, subj: 'THE HOLIDAYS', body: `{ARE YOU ENJOYING THE HOLIDAYS.|DO YOU WANT TO COME AND STAY FOR A FEW DAYS.|WE WENT TO THE SEASIDE. GRANDAD FELL ASLEEP IN THE DECKCHAIR AND GOT BURNT ON ONE SIDE.} {I WILL MAKE YOUR FAVOURITE.|BRING YOUR GAMES.}` },
    ],
    replyDelay: [150, 300],
    reply: [
      { w: (c) => c.said.length > 8 && c.said === c.said.toUpperCase() && /[A-Z]/.test(c.said), secret: 'mail.gran', body: `HELLO {=name}\n\nWHY ARE YOU SHOUTING DEAR. {I CAN HEAR YOU FINE.|IS YOUR BUTTON STUCK AS WELL.} OH. WAIT.\n\nLOVE GRAN XXX\n\nP.S. HOW DO I SEND THIS` },
      { w: (c) => /caps/i.test(c.said), secret: 'mail.gran', body: `HELLO {=name}\n\nTHANK YOU FOR YOUR E-MAIL. GRANDAD HELPED ME OPEN IT.\n\nWHAT IS A CAPS LOCK. I HAVE LOOKED ALL OVER THE KEYBOARD. THERE IS A BUTTON WITH A LITTLE LIGHT BUT I DO NOT WANT TO BREAK IT.\n\nLOVE GRAN XXXX` },
      { w: (c) => c.said.length < 30, secret: 'mail.gran', body: `HELLO {=name}\n\nI GOT YOUR E-MAIL. WAS THAT ALL OF IT. I THINK SOME OF IT FELL OFF ON THE WAY.\n\nGRANDAD SAYS THAT IS HOW YOUNG PEOPLE WRITE NOW.\n\nLOVE GRAN XXX` },
      { w: (c) => /\?/.test(c.said), secret: 'mail.gran', body: `HELLO {=name}\n\nTHANK YOU FOR YOUR LOVELY E-MAIL. IT TOOK GRANDAD AND ME {=n1} GOES TO OPEN IT.\n\nYOU ASKED ME A QUESTION BUT I HAVE FORGOTTEN WHAT IT WAS. THE ANSWER IS YES.\n\n{=wx}\n\nLOVE GRAN XXXX\n\nP.S. HOW DO I SEND THIS` },
      { secret: 'mail.gran', body: `HELLO {=name}\n\nTHANK YOU FOR YOUR E-MAIL. {IT WAS VERY NICE.|I HAVE READ IT THREE TIMES.|GRANDAD PRINTED IT OUT AND IT IS ON THE FRIDGE.} {IT TOOK ME A LONG TIME TO FIND THE REPLY BUTTON.|I AM TYPING THIS WITH ONE FINGER.}\n\n{I HAVE KNITTED YOU SOME MORE SOCKS.|DORIS SAYS HELLO.|THE CAT SAYS HELLO. (IT DOES NOT. IT IS A CAT.)}\n\nLOVE GRAN XXXX\n\nP.S. HOW DO I SEND THIS` },
    ],
    replies: { junked: [{ subj: 'WHY HAVE I GONE IN THE JUNK', body: `{=name}\n\nGRANDAD SAYS YOUR COMPUTER HAS PUT ME IN THE JUNK. I AM NOT JUNK. I AM YOUR GRAN.\n\nI HAVE TOLD YOUR MOM.\n\nLOVE GRAN (NOT JUNK) XXXX` }] },
  });

  // ================================================================ THE COUSIN (Cast 'cousin', a boy or a girl: pop! glitter! the charts!)
  add('kim', {
    from: 'Cousin {cousin} <{cousin?popprince|popprincess}_{cousin.slug}@hotjack.jnet>', addrs: ['{cousin?popprince|popprincess}_{cousin.slug}@hotjack.jnet', '{cousin?popprince|popprincess}_{cousin.slug}@jackmail.webcom', 'popprincess_kim@hotjack.jnet', 'popprincess_kim@jackmail.webcom'], w: 1.8, fx: 'kim', // (the old address still reaches them)
    wrap: '{=hi}\n\n{=body}\n\n{=bye}',
    v: { hi: ['Hiya {=name}!!!', 'heyyy {=name}', 'Hi cuz!!!', '*~* Hiya {=name} *~*', 'Helloooo {=name}!', '{=name}!!!!!'], bye: ['{cousin.first} xXx', 'luv {cousin.first} *~*~*', '{cousin.first} ({cousin.King} of Pop) xx', 'love n hugs, {cousin.first} xoxo', 'byeeee!!! {cousin.first}', '{cousin.first}\n*~*~*~*~*~*~*\n http://www.{cousin.slug}spopzone.kidz/\n*~*~*~*~*~*~*'] },
    ps: ['P.S. sign my slambook!!! http://www.{cousin.slug}spopzone.kidz/', 'P.S. write back or ur not my fave cousin anymore (u are still my fave cousin)', 'P.S. my mom says hi', 'P.S. I put glitter on my mouse mat. bad idea. VERY sparkly hand.'],
    mails: [
      { w: c => c.hasNo1 ? 3 : 0, subj: '{number one!!!|{=no1t}!!!|the charts!!!}', body: `{=no1} is number one {this week|AGAIN|and I KNEW it would be}!!! {I have listened to it {=n2} times.|I know all the words. ALL of them.|I'm doing the dance in my bedroom right now. well not RIGHT now. I'm typing.|it's {so good|ok I guess|my favourite song ever (this week)}.} {What do you think of it??|Do you like it?? you HAVE to like it.|I'm making a page about it on my site.}` },
      { w: c => c.fri ? 3 : 0, subj: '{Top of the Pops tonight!!!|TOTP!!!}', body: `Are you watching Top of the Pops tonight?!?! {I bet {=no1t} is on again.|I'm taping it in case.|My mom makes me hoover during the adverts. there ARE no adverts. it's the BBC.} {ring me after! (when the Internet's off lol)|we can talk about it at Gran's.}` },
      { w: 2, subj: '{my website!!!|NEW on my site|have u seen my page}', body: `I made a NEW page on my site!!! {It's got a slambook.|It's got glitter backgrounds and a song that plays when you go on it.|It's a quiz to see which pop star you are. I am the sporty one. I am not sporty.|It has a counter and it says {=n3} but {=n2} of them are me.} Go on it!!!\n\nhttp://www.{cousin.slug}spopzone.kidz/` },
      { w: 1.5, subj: '{sleepover!!!|SLEEPOVER|this weekend}', body: `I'm having a sleepover {this weekend|on {=tomorrow}|soon}!!! {We're going to watch a scary film and then not sleep.|{cousin?We're having a pillow fight tournament. even my dad.|We're doing makeovers. even my dad.}|We're going to make up a dance routine and film it on my dad's camcorder.} {I'd invite you but you'd just play Game Lad in the corner lol|tell me what film to get!!!}` },
      { w: c => c.crazes.length ? 1.5 : 0, subj: '{=craze}', body: `Have u got into {=craze} yet?? {EVERYONE at my school has.|I am OBSESSED.|my teacher has banned it which means it's even better now.} {=crazeNote}.` },
      { w: c => c.is('valrun') || c.is('valentine') ? 5 : 0, subj: '{valentines!!!|did u get any cards}', body: `{Did u get any Valentine's cards???|I got {=n1} Valentine's cards!!! ok one was from my mom.|Someone put a card in my bag and it's NOT SIGNED.} {Tell me EVERYTHING.|I bet you got one from Gubbinz lol.}` },
      { w: c => c.is('summerhols') ? 2 : 0, subj: '{BORED|summer!!!|holidays}', body: `{I am SOOOO bored.|it's the holidays!!!|We went to the beach and I got sand in my tape player.} {What are you doing?|Come round mine and we can make up dances.|I've watched every video in our house twice.}` },
      { w: c => c.is('y2k') || c.is('advent') ? 2 : 0, subj: '{Christmas list!!!|millennium party!!!}', body: `{My Christmas list is {=n1} pages long.|What are you doing for the MILLENNIUM?!?! It's the biggest party in a THOUSAND YEARS.|I'm going to stay up till midnight on New Year's Eve and my mom CAN'T SAY NO because it's the millennium.} {Write back!!!|I'm so excited I could pop.}` },
      { w: 1, subj: '{guess what|GUESS WHAT|omg guess what}', body: `Guess what!!! {I got a new tape player with a radio in it.|my hamster {cousinpet} had babies. well my mom says {cousinpet} is a {cousinpet?boy|girl} hamster and lives on {cousinpet.his} own so {cousinpet.he} can't have. but there are definitely more hamsters.|I got the highest mark in our class for my spelling test. just saying.|I got my ears pierced!!!} {Your turn. tell me something good.|Write back!!!}` },
    ],
    replyDelay: [60, 140],
    reply: [{ body: `Yaaay u wrote back!!! {I KNEW you would.|Gran said you're good at e-mail.}\n\n{That is SO cool.|lol you are so funny.|I read it out to my mom. she didn't get it.} {Anyway did you see Top of the Pops??|Anyway sign my slambook: http://www.{cousin.slug}spopzone.kidz/|Anyway I have to go, my mom needs the phone.}\n\n{cousin.first} xXx\n\n{=quote}` }],
  });

  // ================================================================ DAVE (best mate. challenges. lowercase.)
  add('dave', {
    from: 'Dave <davetherave@jacknet.jnet>', addrs: ['davetherave@jacknet.jnet', 'dave@hotjack.jnet', 'dave@jackmail.webcom'], w: 3.2, fx: 'kid',
    wrap: '{=hi}{=body}\n\n{=bye}',
    v: { hi: ['', '', 'oi {=name}\n\n', 'alright\n\n', '{=name}!!!\n\n', 'yo {=name}\n\n'], bye: ['dave', 'dave', 'Dave', 'dave\n"the rave"', '-dave', 'from dave (the best at {=game})'], relD: c => c.rel.map(n => n.replace(/ at Dave's/i, ' at MINE')).join(' AND ') },
    ps: ['p.s. mr tiddles says hi', 'p.s. did u eat my crisps at lunch', 'p.s. dont tell my mom i was on the internet', 'p.s. go on my website http://www.davesplace.jnet/', 'p.s. i am still better than u at goldenballs'],
    mails: [
      { w: c => c.hasGame ? 3 : 0, subj: '{{=game}|{=game}!!!!!|ur coming round|rematch}', body: `{=game} at mine {=tomorrow}? {bet you can't beat me|ive been practising|i got a new high score and my mom saw it so it counts|my cousin showed me a secret bit}. {bring ur controller|my mom says u can stay for tea|bring crisps|loser does the washing up}` },
      { w: c => c.fri ? 5 : (c.sat ? 2 : 0), subj: '{weekend|WHAT U DOING THIS WEEKEND|saturday}', body: `what u doing this weekend?? {my cousin is coming round with {=game2}|we could go to the park and do lightspatula fights with the wrapping paper tubes|want to go to the shops on saturday, they might have {=saving}|we could do a four player tournament, i'll do a chart|we could make a film with my dads camcorder}. {ring me. (not when ur on the internet obviously)|my mom says ok if ur mom says ok|im bored already}` },
      { w: c => c.mon && c.school ? 5 : (c.school ? 1 : 0), subj: '{homework|HOMEWORK!!!|did u do it}', body: `did u do the {maths|science|english|french|history} homework?? {i didnt|i did half|i did it on the bus|my dog actually ate it this time not even joking}. {what was question {=n1}|can i copy... i mean CHECK mine against urs|mr bell is going to kill me|i wrote it really small so he cant tell its wrong}` },
      { w: c => c.crazes.length ? 1.5 : 0, subj: '{=craze}', body: `{=craze} {is well good|is so last week|is BANNED at school now, which means everyone is doing it|is basically my whole life now}. {=crazeNote}. {u in?|my brother broke mine|i'm the best in our year}` },
      { w: c => c.cd ? 3 : 0, subj: '{{=cd.name}!!!!!|{=cdline}|COUNTDOWN}', body: `{=cdline}!!!! {i cant wait|i have marked it on my calendar in red|my mom says im not allowed to talk about it at tea anymore|i am going to explode}. {are u excited|we have to be there first|i have already decided what im doing that day: NOTHING ELSE}` },
      { must: c => c.rel.length > 0 && !c.is('xmas') && !c.is('eclipse'), rel: 1, subj: 'ITS TODAY!!!!!!!!!!!!!', body: `ITS TODAY!!!!!! {=relD^}!!!!!! {going to the shop after school|my dad is picking it up on the way home from work|i have been awake since 5|i couldnt sleep}. {come round!!!!|this is the best day of my life (so far)|ring me the SECOND u get home}` },
      { w: 1.2, subj: '{mr tiddles|my cat|CAT EMERGENCY}', body: `{mr tiddles was sick on my controller|mr tiddles sat on the keyboard and deleted my save|mr tiddles has learned how to turn the telly off with his bum|mr tiddles caught a bird and brought it into the kitchen and my mom screamed}. {he is a nightmare|he is the best cat ever though|i am writing this with a cat on my head}` },
      { w: 1.2, subj: '{my website|NEW on my site|go on my site}', body: `{i updated my website|i put a new wrestling match on my site|my website has a counter now and it says {=n3}}. go on it and sign my guestbook!!!\n\nhttp://www.davesplace.jnet/\n\n{its better than urs (joke) (not a joke)|i did the background myself|it plays a midi of my own making}` },
      { w: c => c.tvs.length ? 1.5 : 0, subj: '{did u see {=tv}|{=tv}!!!|last night}', body: `did u see {=tv} last night?? {it was the best one ever|i laughed so much i fell off the sofa|my dad fell asleep and missed the best bit|we have to do that bit at school tomorrow}` },
      { w: c => c.hasNo1 ? 0.8 : 0, subj: 'number one', body: `{=no1} is number one. {its rubbish|my sister keeps singing it. send help|i secretly like it. TELL NO ONE|my mom knows all the words. this is a disaster}` },
      { w: c => c.md >= 1005 ? 2 : 0, subj: '{swap?|pocket critters|got one!!!}', body: `{got a zapachu, want to swap|ive got {=n2} pocket critters now|i need a link cable to trade, can i borrow urs}. {i'll give u my best marble|meet me at the bench at lunch|dont tell {cousin2.first} he will want one}` },
      { w: c => c.is('summerhols') ? 2.5 : 0, subj: '{bored|BORED|come round}', body: `{bored. come round.|its too hot to do anything. lets play {=game} with the curtains shut|my mom says go outside. we could go outside and play {=game} on the game lad}` },
      { w: c => c.is('halloweenrun') || c.is('halloween') ? 4 : 0, subj: '{halloween|costume!!!}', body: `what are u going as for halloween?? {im going as dark mole. i painted my face. it wont come off|im going as a mummy. its toilet roll. my mom is NOT happy|im going as a dalek. EX-TER-MIN-ATE}. {meet at mine at 6|we're doing the whole street}` },
      { w: c => c.is('bonfirerun') ? 3 : 0, subj: 'fireworks', body: `{are u going to the fireworks|my dad bought a rocket called THE ANNIHILATOR}. {it was £{=n1}|it says DO NOT RETURN TO LIT FIREWORK on the side. noted}. {see u there|bring sparklers}` },
      { w: c => c.is('y2k') ? 2 : 0, subj: '{y2k|the bug|millennium}', body: `{if the millennium bug blows up all the computers at school we dont have to do tests|my dad says the bug will stop all the cash machines. i have 47p. i am ready|whats the millennium bug actually do anyway}. {i hope it gets the maths computers|bring it on}` },
      { w: c => c.is('nye') || c.is('betwixt') ? 4 : 0, subj: 'PARTY AT MINE', body: `PARTY AT MINE ON NEW YEARS EVE!!! {my mom says we can stay up till midnight|there will be sausage rolls|bring {=game}}. {its the millennium!!!|this will be the best party in a thousand years|dont be late (dont be early either my mom is hoovering)}` },
    ],
    replyDelay: [35, 90],
    reply: [{ secret: 'mail.dave', subj: '{CHALLENGE|ok then|re: {=re}}', body: `{ok|ha|lol ok|got ur email}\n\nCHALLENGE: beat my score on jacktris: {=score}. {if u beat it u get my shiny card (its not that shiny)|if u beat it i will say {=name} IS THE BEST in assembly|if u dont beat it u have to carry my bag for a week}.\n\nhttp://www.jackattack.jnet/demos.htm\n\n{no cheating|i am watching|go}\n\ndave` }],
  });

  // ================================================================ COUSIN2 (Cast 'cousin2', the cousin's big brother. "the great". knows everything about computers)
  add('ryan', {
    from: '{cousin2} <{cousin2.slug}_the_great@hotjack.jnet>', addrs: ['{cousin2.slug}_the_great@hotjack.jnet', '{cousin2.slug}_the_great@jackmail.webcom', 'ryan_the_great@hotjack.jnet', 'ryan_the_great@jackmail.webcom'], w: 1.6, fx: 'kidlite',
    wrap: '{=hi}\n\n{=body}\n\n{=bye}',
    v: { hi: ['alright cuz', 'alright', 'oi', '{=name}', 'listen'], bye: ['{cousin2.slug}\n"the great"', '{cousin2.slug}', '{cousin2.slug} (the great)', 'r.', '{cousin2.slug}\n-- sent from my K6-2 (basically faster than urs)'] },
    mails: [
      { w: 2, subj: '{my pc|upgrade|my computer is faster than urs}', body: `{got {=n2}MB more RAM. my pc is basically a supercomputer now|overclocked my processor. it gets really hot. i use it to warm my hands|got a new graphics card. games look so real now my mom thinks its the telly|my modem connected at 50K last night. FIFTY. a new record}. {whats yours on?|dont argue, mines faster|ur pc is basically a calculator}` },
      { w: 1.5, subj: '{tips|computer tips from a pro|listen}', body: `some tips from a pro:\n- {defrag every week. it makes the little blocks go in the right places and its relaxing to watch|never download anything off the internet. except my tips|dont open attachments, remember melissa|if it crashes, give it a little tap on the side}\n- {the turbo button does nothing. press it anyway|never let ur mom see the phone bill|never eat crisps near the keyboard}\n- {cousin2.slug} is always right` },
      { w: c => c.hasGame ? 1.5 : 0, subj: '{=game}', body: `{=game} is {overrated|alright i guess|basically the same as the last one|actually quite good (dont quote me)}. {i finished it in a day|i got bored on the second level|my mate's brother says theres a secret level but you have to have 100%}. {get something better|its no {=game2} though}` },
      { w: 1, subj: '{ur website|i looked at ur website}', body: `went on ur website again. {its ok. too yellow|the counter says {=n3}. thats basically all me|you should get a guestbook. oh u have one. it has my name in it 12 times}. {not bad for a beginner|i could do it better but i cant be bothered}` },
      { w: c => c.is('y2k') ? 3 : 0, subj: 'y2k is rubbish', body: `y2k is rubbish. {computers just use two numbers for the year, so 99 goes to 00 and some old ones think its 1900. thats it|my dad's bank has spent millions on it. i could have fixed it for a fiver|my pc is fine. i tested it. nothing happened. boring}. {everyone needs to calm down|ill be laughing on new years day}` },
      { w: 1, subj: '{99%|downloading|still downloading}', body: `downloading a {demo|patch|video of a cat} at {=n1}KB a second. {it says {=n2} minutes left. it said that an hour ago|if anyone picks up the phone im going to cry|its on 99%. its been on 99% since tea}` },
    ],
    reply: [{ body: `lol. anyway. {i already knew that|thats basically what i said|ok but my computer is still faster}.\n\n{cousin2.slug}\n"the great"\n\n{=quote}` }],
  });

  // ================================================================ GUBBINZ (the little green helper who lives in the computer)
  add('gubbinz', {
    from: 'Gubbinz <gubbinz@squigpen.grot>', addrs: ['gubbinz@squigpen.grot'], w: 2.2, fx: 'typo',
    wrap: '{=hi}\n\n{=body}\n\n{=bye}',
    v: { hi: ['Hi {=name}!', 'HELLO {=name^}!!!', 'It looks like you\'re reading an e-mail! Would you like help?', 'Psst. {=name}.', '{=name}. Listen.'], bye: ['- G', 'Gubbinz (inside the computer)', 'WAAAGH!\nGubbinz', 'Gubbinz\nYour Desktop Helper (TM)', '- Gubbinz (your best helper)'] },
    ps: ['P.S. I ate the mouse ball. Sorry.', 'P.S. Don\'t tell Jack I was on the e-mail.', 'P.S. If the cursor goes wobbly, that\'s me.', 'P.S. I hid something in the Recycle Bin. Heh heh.', 'P.S. Defrag is very relaxing. All the little blocks. Like Blockology that plays itself.'],
    mails: [
      { w: 2, subj: '{hello|HELLO|it\'s me|a message from inside the computer}', body: `I am still in the computer. {It is warm in here because of the fan.|I have been living in the Temp folder. Nobody looks in there.|I found a file called {SYSTEM.INI|AUTOEXEC.BAT|COMMAND.COM} and I ate a bit of it. It tasted like numbers.|I have made a little house out of floppy disks.} {Do not turn me off.|The little hourglass is my friend.|When the modem goes, I dance.}` },
      { w: 2, subj: '{RUPEES|i need rupees|rupees rupees rupees}', body: `I need some Rupees. {I want a Game Lad Color. A red one. Red ones go faster.|Da Gem Exchange has got a sale on.|I sold Jack's {spare dice|best paintbrush|lunch} for {=n1} Rupees.} {Can you lend me some Rupees? I will pay you back. Probably.|Rupees are money. Money is Rupees. That is economics.|http://www.gemexchange.grot/}` },
      { w: 1.5, subj: '{HELP|helpful tips|a tip from Gubbinz}', body: `{It looks like you are trying to play Goldenballs at 2am. Would you like me to tell your Mom?|Tip: if a game crashes, blow on the cartridge. If it is a CD, do not blow on it. I learnt that the hard way.|Tip: the Game Lad goes further on fresh batteries. I ate the old ones.} {I am very helpful.|You are welcome.|Click me for more tips. Do not click me. I am in your e-mail.}` },
      { w: 1.5, subj: '{jack\'s desk|the bits box|making stuff}', body: `Jack is making things again. {He is painting an Ork red because red ones go faster.|He has a bits box. It is FULL of good bits. I sleep in it sometimes.|He got AirMix glue on his fingers and stuck to a Spitfire.|He built a BLOCKO spaceship and I am the pilot now.|He is doing his Rubrick\'s cube under the table at tea time. Mom knows.} {Making stuff is the best.|WAAAGH!|One day I will be a model kit too.}` },
      { w: c => c.hasGame ? 1.2 : 0, subj: '{=game}', body: `What is this {=game} thing everyone keeps going on about? {Can you eat it?|Has it got a cheat code?|I tried to play it. I pressed all the buttons at once. It was very good.|Does it go faster if you paint it red?}` },
      { w: c => c.cd ? 1.2 : 0, subj: 'countin', body: `{=cdline}! I have been counting on me fingers. {I ran out of fingers.|I used the calculator as well.|Then I ate the calendar.} {Is it a game? Has it got a boss level?|Wake me up when it comes.}` },
      { w: c => c.is('y2k') ? 2 : 0, subj: 'the millennium bug', body: `Everyone is scared of the Millennium Bug. {I have been looking for it in the computer. I found a little bug but it was just a crumb.|I am going to catch it and keep it as a pet.|Bugs are crunchy. I am not scared.} {Leave it to me.|I will squash it like a Blockology line.}` },
      { w: c => c.is('halloween') || c.is('halloweenrun') ? 2 : 0, subj: 'halloween', body: `For Halloween I am going as {a Dalek|a Game Lad|Jack|a floppy disk}. {Nobody was scared.|One lady gave me a apple. I wanted Rupees.}` },
      { w: c => c.is('xmas') || c.is('advent') ? 2 : 0, subj: 'Christmas', body: `I have written to Father Christmas. {I asked for an ULTRA 64.|I asked for all the Rupees in the world.|I asked for a red one. Of anything.} {I have been good. Mostly.|I only ate one mince pie. And the plate.}` },
    ],
    replyDelay: [45, 120],
    reply: [{ secret: 'mail.gubbinz', body: `HELLO {=name^}!\n\nYou wrote to me! {Nobody writes to me.|I am so happy I ate a bit of the keyboard.|I read it out to the screen saver. It liked it.}\n\n{I have put your e-mail in my special folder.|I will tell all the other programs in the computer.|You are now an honorary Desktop Helper.}\n\nWAAAGH!\nGubbinz\n\n{=quote}` }],
  });

  // ================================================================ JACK (the editor of JACK ATTACK! Online)
  add('jack', {
    from: 'Jack (JACK ATTACK! Online) <jack@jackattack.jnet>', w: c => c.guest ? 1.4 : 1.6,
    mails: [
      { must: c => c.first && c.member, subj: 'WELCOME TO JACKNET, {=name}!!!', body: `WELCOME TO JACKNET, {=name}!!!\n\nThis is Jack, the editor of JACK ATTACK! Online. {You're member number {=no}!|You made it!} That name is yours now. Nobody else can be {=name}. Not even me.\n\nNow that you're a member you can:\n * Post on the Forums: http://www.jackattack.jnet/forums.htm\n * Write on the Letters page: http://www.jackattack.jnet/letters.htm\n * Hang out with everyone: http://www.jackattack.jnet/hangout.htm\n * Have your own desktop that follows you to any computer (like magic, but with modems)\n\nDon't tell anyone your password. Not even Dave. ESPECIALLY not Dave.\n\nMay the Force be with you!\nJack\nEditor, JACK ATTACK! Online\n\nP.S. Gubbinz says hello. He's been told not to eat your e-mail.` },
      { w: c => c.member ? 2 : 1, subj: '{Get Uh-Oh! and add your mates|Have you got Uh-Oh! yet?|Uh-oh!!!}', body: c => `Hi {=name}!\n\n{Have you found Uh-Oh! Messenger yet?|Quick tip from the Editor:} It's the little flower by the clock, and the contact list on the right of the screen. It goes "uh-oh!" when someone sends you a message. (Turn your speakers on.)\n\n${c.member && c.no ? 'Your Uh-Oh! number is ' + (1999000 + c.no * 37) + '. It\'s yours forever. Give it to your mates, and add theirs with Add/Find Users. They have to say OK first, just like the real thing.' : 'Join JackNet (it\'s free!) and you get your own Uh-Oh! number to give to your mates. Guests get a number too, but it changes every time.'}\n\nYou can send messages to people even when they're offline. They get them next time they log on.\n\nOne rule: never give out your real name, address, school or phone number. Not even to nice people.\n\n{Jack|Jack (Editor)|Jack\nJACK ATTACK! Online}` },
      { w: c => c.guest ? 3 : 0, subj: '{You should JOIN!!!|Pick your own name!|A message from the Editor}', body: `Hi {=name}!\n\n{Thanks for visiting JACK ATTACK! Online!|I noticed you've been looking round the site. Cool!} Right now you're a guest, which means you're called "{=name}". That's a bit boring.\n\nIf you join JackNet (it's FREE!) you can pick your OWN name, post on the forums, and your desktop follows you to any computer. Just log on with a name and a password: that's you signed up!\n\nhttp://www.jackattack.jnet/login.htm\n\n{Cowabunga!|See you around!}\nJack` },
      { w: 2, subj: '{Thanks for coming back!|You\'re a legend|Hello from the Editor}', body: `Hi {=name}!\n\n{Thanks for coming back to JACK ATTACK! Online!|It's Jack here, from the website. I saw you were on today!|Just wanted to say thanks for visiting.} {You're one of my favourite visitors. (Dave is not one of my favourite visitors.)|The counter's gone up loads this week, and I think quite a lot of that is you.}\n\n{Have you tried JACKTRIS yet? Beat my high score. You won't: http://www.jackattack.jnet/demos.htm|Have you seen Gubbinz's page? He's been redecorating: http://www.jackattack.jnet/grot.htm|Write me a letter for the Letters page! I read them all: http://www.jackattack.jnet/letters.htm|Come and say hi in the Hangout: http://www.jackattack.jnet/hangout.htm}\n\n{Right now I'm playing {=game}.|At the moment I'm {=mood}}\n\n{Laters!|Cheers,|See ya,}\nJack` },
      { w: c => c.posts.length ? 2 : 0, subj: '{NEW on JACK ATTACK!|What\'s new on the site|Site update!}', body: c => `Hi {=name}!\n\nHere's what's new on JACK ATTACK! Online this week:\n\n${c.posts.slice(0, 4).map(p => ' * [' + p.tag + '] ' + p.text).join('\n\n')}\n\nCome and have a look: http://www.jackattack.jnet/\n\n{Woo-hoo!|See you on the site!}\nJack` },
      { w: 1, subj: '{Can you help me test something?|A favour|Secret mission}', body: `Hi {=name},\n\n{I'm building something new for the site and I need testers.|I've hidden a new secret somewhere on this computer.|Somebody told me there's a secret in the Start > Run box. I'm not saying if they're right.} {Can you have a poke around and tell me if anything breaks?|Look in places nobody looks.|Try right-clicking things. And double-clicking things. And typing things.}\n\nDon't tell Dave.\n\nJack` },
      { must: c => c.is('xmas') && c.member, subj: 'Merry Christmas from JACK ATTACK!', card: (c, r) => ({ art: 'tree', title: 'Merry Christmas!', msg: `Merry Christmas ${c.name}! Thanks for being a JACK ATTACK! member this year. Have a brilliant Christmas, eat loads, and see you in the year 2000!`, from: 'Jack', fromAddr: 'Jack <jack@jackattack.jnet>' }), body: `Hi {=name}!\n\nI've sent you a Christmas card! To see it, go to:\n\nhttp://www.greetzomatic.kidz/pickup/{=code}.html\n\nMerry Christmas and a Happy Millennium!\nJack` },
    ],
  });

  // ================================================================ PEN PALS (each user gets their own)
  const PALS = [
    { n: 'Lars', a: 'lars.blocks@fjordnet.netz', where: 'Norway', bits: ['It is very dark here in winter. In summer it is light nearly all night!', 'I go skiing at the weekend. My little brother is faster than me. This is not fair.', 'My favourite game is Blockology. I am VERY good at Blockology.', 'We eat a lot of fish. I would rather eat pizza.'], sign: 'Your friend from Norway,\nLars' },
    { n: 'Sofie', a: 'sofie_k@penpalpals.infobahn', where: 'Denmark', bits: ['Everyone here rides a bike, even my grandmother.', 'The little plastic bricks come from my country! I have a whole box of them.', 'I like drawing horses and playing computer games with my brother.', 'It rains a lot here too. Maybe it is the same rain as you!'], sign: 'Hugs from Denmark,\nSofie' },
    { n: 'Marco', a: 'marco.palla@penpalpals.infobahn', where: 'Italy', bits: ['Football is the most important thing here. After pizza. And my Mamma.', 'My English is not so good, I am practising with you!', 'I have a PlaySpace and I play football games every day.', 'In summer it is very hot. We eat ice cream every day. Gelato!'], sign: 'Ciao!\nMarco' },
    { n: 'Aoife', a: 'aoife.ceol@penpalpals.infobahn', where: 'Ireland', bits: ['I do Irish dancing. My feet are very tired.', 'It rains here nearly every day. My Mammy says that is why everything is so green.', 'I am learning the tin whistle. My Daddy wears earmuffs.', 'My brother says your computer is better than ours. Is it?'], sign: 'Slán for now,\nAoife' },
    { n: 'Kasia', a: 'kasia.k@penpalpals.infobahn', where: 'Poland', bits: ['In winter there is lots of snow here. We build snow forts!', 'My English teacher says I must write to you every week. I am happy to do it!', 'I like Rubrick\'s cubes and computer games. I can do one side of the cube.', 'My grandmother makes the best dumplings in the world.'], sign: 'Best wishes from Poland,\nKasia' },
  ];
  const palOf = c => PALS.find(p => p.a === c.to0) || PALS[G.hash(String(c.addr)) % PALS.length]; // your own pen pal (or whoever you wrote to)
  add('penpal', {
    from: '{=palFrom}', w: 0.7,
    mails: [
      { from: '{=palFrom}', subj: '{Hello from {=palWhere}!|A letter from your pen pal|Hello again!|Re: hello}', body: `Dear {=name},\n\n{How are you? I am fine.|Thank you for being my pen pal!|I hope you are well. Here everything is good.} {=palBit}\n\n{=palBit2}\n\n{What games do you like?|Is it true that in England you eat beans for breakfast?|What is your school like? Mine has a computer room with six computers.|Please write back and tell me about your week!}\n\n{=palSign}\n\nP.S. {I found you on the Pen Pals page: http://www.jackattack.jnet/penpals.htm|Please reply to me, I check my e-mail every day!}` },
    ],
    v: { palFrom: c => `${palOf(c).n} <${palOf(c).a}>`, palWhere: c => palOf(c).where, palBit: (c, r) => G.pick(palOf(c).bits, r), palBit2: (c, r) => G.pick(palOf(c).bits, r), palSign: c => palOf(c).sign },
    addrs: PALS.map(p => p.a),
    replyDelay: [90, 200],
    reply: [{ from: '{=palFrom}', secret: 'mail.penpal', body: `Dear {=name},\n\nThank you for your letter! I was so happy when I saw it. {I read it to my whole class.|My mother says your English is very good. (It is your language, I told her.)} {=palBit}\n\nPlease write again soon!\n\n{=palSign}\n\n{=quote}` }],
  });

  // ================================================================ SCHOOL (Homework Club, Computer Club)
  add('school', {
    from: 'Mrs Hargreaves <homework@skool.kidz>', addrs: ['homework@skool.kidz', 'computerclub@skool.kidz', 'maths@skool.kidz'], w: c => c.school || (c.sun && c.term) ? 2 : 0,
    mails: [
      { w: c => c.mon || c.sun ? 3 : 1, subj: '{Homework Club reminder|Homework this week|Don\'t forget!}', body: `Dear Homework Club,\n\n{This week's homework is|A reminder that this week we have}:\n\n * {A book review (one page, neat handwriting please)|A poem about {=season} (it does not have to rhyme)|Spelling test on Friday: words from the green sheet|A story called "The Day the Computers Stopped" (ONE page, not twelve)|A project on the Romans (no, you can't just print out a web page)}\n * {Times tables practice (the 7s and 8s)|Read for twenty minutes every night|Bring in a cereal box for the model-making}\n\n{Please remember: "the modem ate it" is not an excuse.|Neat handwriting, please. Especially you, {=name}.|If you need help, Homework Club is on Tuesdays in Room 6.}\n\nMrs Hargreaves` },
      { from: 'Mr Bell (Maths) <maths@skool.kidz>', w: 1, subj: '{Maths test|Maths homework|Fractions}', body: `Hello {=name},\n\n{Just a reminder that there's a maths test on {=tomorrow}.|Your fractions homework is due in on {=tomorrow}.|Some of you put "whatever I want it to be" for x again. It is not whatever you want it to be.} {Please revise chapter {=n1}. Not a different chapter.|Calculators are allowed. Calculators on the computer are not.}\n\nMr Bell` },
      { from: '{teacher} (Computer Club) <computerclub@skool.kidz>', w: 1, subj: '{Computer Club this week|Computer Club!|Room 14}', body: `Dear Computer Club,\n\n{This week we're making web pages! Bring your ideas (and a floppy disk).|This week: Logo. We will be teaching the turtle to draw a rocket.|This week we're learning to touch-type. Please don't look at the keys.|This week we're defragmenting the school computers. It takes the whole lunchtime. It's very relaxing.} {Please remember the printer is out of cyan.|Please don't change the desktop wallpaper again.|Room 14, lunchtime, as usual.}\n\nhttp://room14.cyb/\n\n{teacher}` },
      { w: c => c.is('endofterm') ? 5 : 0, subj: 'End of term', body: `Dear all,\n\n{Have a lovely holiday!|Well done for all your hard work this term.} {Please take ALL of your belongings home, including the PE kit that's been in the cloakroom since September.|Reports will be posted home.} {Read some books!|See you next term.}\n\nMrs Hargreaves` },
    ],
    noreply: 1,
  });

  // ================================================================ THE FOOTBALL TEAM (Sunday league, September to May)
  add('coach', {
    from: 'Coach Terry <coach@roversjuniors.jnet>', addrs: ['coach@roversjuniors.jnet'], w: c => (c.m >= 9 || c.m <= 5) && (c.fri || c.sat) && !(c.md >= 1218 || c.md <= 104) && !c.is('easterhols') ? 1.5 : 0,
    mails: [
      { subj: '{Sunday\'s match|Match on Sunday!|Rovers Juniors - this Sunday}', body: `Rovers Juniors - this Sunday\n\nKick-off: {ten|half ten|eleven} o'clock. Please be there 20 minutes early.\nBring: shin pads, boots, a drink. {Wellies for the walk across the field.|Gloves. It's going to be freezing.}\n\nOranges this week: {=name} {(please bring two bags)|(sorry, it's your turn)|(don't forget like last time)}.\n\n{Last week's result: we lost {=n1}-0. But we tried really hard.|Last week's result: 2-2! Brilliant! Even if one of ours was an own goal by them.|Last week we won! The first time this season! Well done everyone.}\n\nhttp://roversjuniors.jnet/\n\nCoach Terry` },
    ],
    reply: [{ body: `Thanks {=name}, see you Sunday. Don't forget the oranges!\n\nCoach Terry\n\n{=quote}` }],
  });

  // ================================================================ THE POSTMAN: bounces and the Unsubscribe-o-Matic
  add('mailer', {
    replyOnly: 1, from: 'Mail Delivery Subsystem <MAILER-DAEMON@mail.jacknet.jnet>',
    replies: {
      bounce: [{ from: 'Mail Delivery Subsystem <MAILER-DAEMON@mail.jacknet.jnet>', subj: 'Undeliverable: {=re}', secret: 'mail.bounce', body: `This is the mail system at host mail.jacknet.jnet.\n\nI'm sorry to have to inform you that your message could not be delivered to one or more recipients.\n\n<{=to0}>: {550 User unknown. (Did you spell it right? Did they?)|552 Mailbox full. (They have 4,000 chain letters in there.)|554 This address does not accept replies. It only sends. It is a one-way street.|550 Recipient has moved to a bigger modem and left no forwarding address.|451 The server is having its tea. Try again later.}\n\n{Please do not reply to this message. I am a robot. I would not understand.|For help, ask somebody over the age of twelve.}\n\n----- The original message -----\n{=quote}` }],
      unsub: [{ from: 'The Unsubscribe-o-Matic <robot@unsubomatic.netz>', subj: 'Your unsubscribe request', body: `Dear {=name},\n\nThank you for asking to UNSUBSCRIBE.\n\n{Your request has been received and will be processed in 6 to 8 weeks.|Unfortunately the word "unsubscribe" contained a spelling mistake. (It didn't. We just say that.)|Our robot read "UNSUBSCRIBE" as "SUBSCRIBE TO TWO MORE".} {You have now been subscribed to: The Daily Pebble, and Spoon Collectors Monthly.|While you wait, here is a copy of our newsletter.|Please do not reply to this e-mail, or you will be unsubscribed from being unsubscribed.}\n\nHave a nice day!\nThe Unsubscribe-o-Matic\nhttp://www.unsubomatic.netz/` }],
    },
  });

  // ================================================================ THE CHAIN LETTER (it always comes back)
  const CHAINS = [
    ['DON\'T BREAK THE CHAIN!!! (VERY LUCKY)', `THIS IS THE LUCKY ROBOT OF THE INTERNET!!!\n\n     (o o)\n    ( vvv )\n\nThis e-mail has been round the world {=n2} times. Send it to 10 people in the next 10 minutes and your favourite game will come out EARLY.\n\nIf you break the chain, your Game Lad batteries will run out at the exciting bit.\n\nThis is TRUE. A boy in America did not send it and his Eggbert ran away.`],
    ['SEND THIS TO 10 PEOPLE (no joke)', `A big computer company is TESTING a new e-mail tracker. For every person you send this to, they will pay you £5!!! My friend's cousin got £{=n3}!!!\n\nSEND THIS TO EVERYONE YOU KNOW!!!\n\n(Their lawyer said it is definitely real.)`],
    ['make a wish!!! (forward to 5 friends)', `Make a wish. Go on. Now scroll down.\n\n\n\n\n\nkeep going\n\n\n\n\n\nnearly there\n\n\n\n\n\nNow send this to 5 friends and your wish will come true in 5 days! Send it to 10 friends and it will come true in 3 days! Send it to nobody and Gubbinz will eat your wish.`],
    ['THE WISHING WHALE', `This is the Wishing Whale. It brings good luck to everyone who forwards it.\n\n   .-""-.\n  / o  o \\\n  \\ vvvv /\n   '----'\n\nOne man forwarded it and found 10p on the pavement. One girl did NOT forward it and stepped in a puddle in her new shoes.\n\nDON'T LET THIS HAPPEN TO YOU!!! SEND IT ON!!!`],
  ];
  const CHAIN_FROM = Cast.deep(['Cousin {cousin} <{cousin?popprince|popprincess}_{cousin.slug}@hotjack.jnet>', '{cousin2} <{cousin2.slug}_the_great@hotjack.jnet>', 'Gran <gran.and.grandad@jacknet.jnet>', 'Dave <davetherave@jacknet.jnet>', '{kidVal} <{kidVal.slug}.w@hotjack.jnet>', 'N64Kid <n64kid@hotjack.jnet>', 'Auntie Pat <pat.and.ken@pensionernet.jnet>', '{club3} <yoyo_{club3.slug}@hotjack.jnet>']);
  const NAMES = Cast.deep(['{cousin.first}', '{cousin2}', '{kidVal}', '{kidSoon}', '{club3}', '{kidPoke}', 'Auntie Pat', 'Doris', 'Mike', '{kidEp1}', '{club1}', 'Kevin', '{club2}', 'N64Kid', '{kidY2k}', '{kidBand}']);
  function chainMail(c, r, n) {
    const ch = G.pick(CHAINS, r), fw = 'FW: '.repeat(Math.max(1, Math.min(14, n)));
    const people = Array.from({ length: Math.min(6, n) }, () => G.pick(NAMES, r));
    let body = G.expand(ch[1], c, r);
    people.forEach(p => { body = `${p}: ${G.pick(['send it on!!!', 'this is real!!', 'i sent it to everyone', 'dont break it', 'my mom did this one', 'IT WORKED FOR ME'], r)}\n` + body.split('\n').map(l => (l[0] === '>' ? '>' : '> ') + l).join('\n'); });
    return { subj: (fw + ch[0]).trim(), body: `${G.pick(['dont break the chain!!!', 'sorry, had to!!!', 'i didnt want to risk it', 'SEND IT ON', 'this one is REAL'], r)}\n\n${body}\n\n------------------------------\nThis chain has been forwarded ${n} time${n > 1 ? 's' : ''}.${n >= 10 ? ' It is now longer than the e-mail. It has its own postcode.' : ''}` };
  }
  add('chain', {
    from: '{=chainFrom}', w: 1, v: { chainFrom: CHAIN_FROM },
    mails: [{ chain: 3, subj: 'x', body: 'x', after: (o, c, r) => { const n = G.between(3, 9, r), m = chainMail(c, r, n); o.subj = m.subj; o.body = m.body; o.chain = n; o.from = G.pick(CHAIN_FROM, r); } }],
    replies: { back: [{ from: '{=chainFrom}', chain: 1, rawsubj: 1, subj: '{=chainFw}DON\'T BREAK THE CHAIN', body: `x`, then: null }] },
  });
  // the chain reply is built by hand so it gets longer every time
  const back = G.T.chain.replies.back[0];
  back.body = '{=chainBody}';
  G.T.chain.v.chainBody = (c, r) => chainMail(c, r, (c.chainN || 3) + 1).body;
  G.T.chain.v.chainFw = c => 'FW: '.repeat(Math.min(14, (c.chainN || 3) + 1));
})();
